pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address payable caller, uint256 depositAmount, uint256 reentrantAmount) public {
        depositAmount = bound(depositAmount, 1, 1e18);
        reentrantAmount = bound(reentrantAmount, 1, 1e18);
        vm.deal(caller, depositAmount + reentrantAmount);

        // Deposit initial amount
        vm.prank(caller);
        c.addToBalance{value: depositAmount}();
        uint256 balanceBefore = c.getBalance(caller);

        // Call withdrawBalance which should reset balance to 0; reentrant call to addToBalance
        vm.prank(caller);
        (bool success, ) = address(c).call{value: reentrantAmount}(abi.encodeWithSignature("withdrawBalance()"));

        uint256 balanceAfter = c.getBalance(caller);

        // The rule: Balance should not increase; if withdraw succeeds, it should be 0, if it reverts, it should be unchanged
        assertTrue(balanceAfter <= balanceBefore);
    }
}

