pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address sender, uint256 deposit1, uint256 deposit2) public {
        vm.assume(sender != address(0));
        vm.assume(deposit1 <= address(this).balance && deposit2 <= address(this).balance);

        // Initial balance
        uint256 initialBalanceSender = c.getBalance(sender);

        // First deposit
        vm.deal(sender, deposit1);
        vm.prank(sender);
        (bool success1, ) = address(c).call{value: deposit1}(abi.encodeWithSignature("addToBalance()"));

        // If first deposit succeeded, send another deposit
        if (success1) {
            vm.deal(sender, deposit2);
            vm.prank(sender);
            (bool success2, ) = address(c).call{value: deposit2}(abi.encodeWithSignature("addToBalance()"));

            // After both calls, balance should be initial + deposit1 + deposit2 (if both succeeded)
            uint256 expectedBalance = initialBalanceSender + (success1 ? deposit1 : 0) + (success2 ? deposit2 : 0);
            uint256 actualBalance = c.getBalance(sender);
            assertTrue(actualBalance == expectedBalance, "Balance invariant violated after reentrant addToBalance");
        } else {
            // If first call failed, balance unchanged
            assertTrue(c.getBalance(sender) == initialBalanceSender, "Balances should be unchanged on failure");
        }
    }
}

