pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint256 amount1, uint256 amount2) public {
        vm.assume(sender != address(0));
        vm.assume(amount1 <= 1e18);
        vm.assume(amount2 <= 1e18);

        // Track total Ether sent
        uint256 totalSent = amount1 + amount2;

        // First call to addToBalance
        vm.deal(sender, amount1);
        vm.prank(sender);
        (bool success1, ) = address(c).call{value: amount1}(abi.encodeWithSignature("addToBalance()"));
        if (!success1) { totalSent -= amount1; }

        // Second call to addToBalance
        vm.deal(sender, amount2);
        vm.prank(sender);
        (bool success2, ) = address(c).call{value: amount2}(abi.encodeWithSignature("addToBalance()"));
        if (!success2) { totalSent -= amount2; }

        // Assert contract balance equals total successful deposits
        assertTrue(address(c).balance == totalSent);
    }
}

