pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 amount) public {
        vm.deal(caller, amount);
        vm.prank(caller);
        uint256 beforeBalance = address(c).balance;
        uint256 callerBefore = c.getBalance(caller);

        (bool success, ) = address(c).call{value: amount}(abi.encodeWithSelector(c.addToBalance.selector));

        if (success) {
            uint256 afterBalance = address(c).balance;
            uint256 callerAfter = c.getBalance(caller);
            assertTrue(afterBalance == beforeBalance + amount && callerAfter == callerBefore + amount, "balance invariant broken");
        } else {
            uint256 afterBalance = address(c).balance;
            uint256 callerAfter = c.getBalance(caller);
            assertTrue(afterBalance == beforeBalance && callerAfter == callerBefore, "revert should not change state");
        }
    }
}

